1	const PROCESSING_FEE = 5;
2	
3	const BASE_PREMIUM_BY_ITEM_TYPE = {
4	  sword: 100,
5	  amulet: 60,
6	  staff: 80,
7	  potion: 40,
8	  rune: 25,
9	  moonstone: 25,
10	} as const satisfies Record<string, number>;
11	
12	type InsurableItemType = keyof typeof BASE_PREMIUM_BY_ITEM_TYPE;
13	
14	const INSURANCE_VALUE_BY_ITEM_TYPE = {
15	  sword: 1000,
16	  amulet: 600,
17	  staff: 800,
18	  potion: 400,
19	  rune: 250,
20	  moonstone: 250,
21	} as const satisfies Record<InsurableItemType, number>;
22	
23	const DEDUCTIBLE_PER_DAMAGE = 100;
24	
25	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
26	
27	const BLOCK_SIZE = 3;
28	
29	const BLOCK_BASE_PREMIUM = 60;
30	
31	const CURSE_SURCHARGE_RATE = 0.5;
32	
33	const HIGH_ENCHANTMENT_THRESHOLD = 5;
34	
35	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
36	
37	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
38	
39	const LOYALTY_YEARS_THRESHOLD = 2;
40	
41	const LOYALTY_DISCOUNT_RATE = 0.2;
42	
43	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
44	
45	export type QuoteResult = { premium: number };
46	
47	export type ClaimResult = { payout: number; remainingCap: number };
48	
49	export type ScenarioResult = QuoteResult | ClaimResult;
50	
51	export type ScenarioOutcome = { results: ScenarioResult[] };
52	
53	type Item = {
54	  type: InsurableItemType;
55	  cursed?: boolean;
56	  enchantment?: number;
57	};
58	
59	type Customer = { yearsWithMHPCO: number };
60	
61	type QuoteStep = { op: "quote"; items: Item[] };
62	
63	type Damage = { itemType: string; amount: number };
64	
65	type ClaimStep = {
66	  op: "claim";
67	  policy: number;
68	  incident: { cause: string; damages: Damage[] };
69	};
70	
71	type Step = QuoteStep | ClaimStep;
72	
73	type Scenario = { customer: Customer; steps: Step[] };
74	
75	// Amounts are rounded in the MHPCO's favour: premiums (charged to the
76	// customer) round up.
77	const roundPremiumInMHPCOsFavour = (amount: number): number =>
78	  Math.ceil(amount);
79	
80	const countByItemType = (items: Item[]): Map<InsurableItemType, number> => {
81	  const counts = new Map<InsurableItemType, number>();
82	
83	  for (const item of items) {
84	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
85	  }
86	
87	  return counts;
88	};
89	
90	// Exactly 3 alike components form a building block at a special base premium.
91	const basePremiumForAlikeItems = (
92	  type: InsurableItemType,
93	  count: number,
94	): number =>
95	  count === BLOCK_SIZE
96	    ? BLOCK_BASE_PREMIUM
97	    : count * BASE_PREMIUM_BY_ITEM_TYPE[type];
98	
99	const basePremiumOf = (items: Item[]): number =>
100	  [...countByItemType(items)]
101	    .map(([type, count]) => basePremiumForAlikeItems(type, count))
102	    .reduce((total, premium) => total + premium, 0);
103	
104	const ownBasePremiumOf = (item: Item): number =>
105	  BASE_PREMIUM_BY_ITEM_TYPE[item.type];
106	
107	// Item-specific modifiers apply to the affected item's own base premium,
108	// not to the policy total.
109	type ItemModifier = { appliesTo: (item: Item) => boolean; rate: number };
110	
111	const CURSE_MODIFIER: ItemModifier = {
112	  appliesTo: (item) => item.cursed === true,
113	  rate: CURSE_SURCHARGE_RATE,
114	};
115	
116	const HIGH_ENCHANTMENT_MODIFIER: ItemModifier = {
117	  appliesTo: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
118	  rate: HIGH_ENCHANTMENT_SURCHARGE_RATE,
119	};
120	
121	const ITEM_MODIFIERS: ItemModifier[] = [
122	  CURSE_MODIFIER,
123	  HIGH_ENCHANTMENT_MODIFIER,
124	];
125	
126	const itemSurchargeOf = (items: Item[], modifier: ItemModifier): number =>
127	  items
128	    .filter(modifier.appliesTo)
129	    .reduce((total, item) => total + ownBasePremiumOf(item) * modifier.rate, 0);
130	
131	// Item modifiers accumulate: an item matching several of them pays each
132	// surcharge on its own base premium.
133	const itemSurchargesOf = (items: Item[]): number =>
134	  ITEM_MODIFIERS.reduce(
135	    (total, modifier) => total + itemSurchargeOf(items, modifier),
136	    0,
137	  );
138	
139	// Policy-wide modifiers are computed from the policy base premium, so the
140	// first insurance surcharge is 10 % of the base — not of base plus curse.
141	// A modifier's rate is signed: surcharges are positive, discounts negative.
142	type PolicyContext = { customer: Customer; precedingQuotes: number };
143	
144	type PolicyModifier = {
145	  appliesTo: (context: PolicyContext) => boolean;
146	  rate: number;
147	};
148	
149	const FIRST_INSURANCE_MODIFIER: PolicyModifier = {
150	  appliesTo: () => true,
151	  rate: FIRST_INSURANCE_SURCHARGE_RATE,
152	};
153	
154	const LOYALTY_MODIFIER: PolicyModifier = {
155	  appliesTo: ({ customer }) =>
156	    customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD,
157	  rate: -LOYALTY_DISCOUNT_RATE,
158	};
159	
160	// Each item in a quote counts as a first insurance regardless of customer
161	// history, so this discount stacks with the first insurance surcharge.
162	const FOLLOW_UP_CONTRACT_MODIFIER: PolicyModifier = {
163	  appliesTo: ({ precedingQuotes }) => precedingQuotes >= 1,
164	  rate: -FOLLOW_UP_CONTRACT_DISCOUNT_RATE,
165	};
166	
167	const POLICY_MODIFIERS: PolicyModifier[] = [
168	  FIRST_INSURANCE_MODIFIER,
169	  LOYALTY_MODIFIER,
170	  FOLLOW_UP_CONTRACT_MODIFIER,
171	];
172	
173	// Policy modifiers accumulate: each applicable one is computed on the same
174	// policy base premium, never compounded on top of another.
175	const policyAdjustmentOf = (
176	  basePremium: number,
177	  context: PolicyContext,
178	): number =>
179	  POLICY_MODIFIERS.filter((modifier) => modifier.appliesTo(context)).reduce(
180	    (total, modifier) => total + basePremium * modifier.rate,
181	    0,
182	  );
183	
184	const quotePremium = (items: Item[], context: PolicyContext): number => {
185	  const basePremium = basePremiumOf(items);
186	
187	  return roundPremiumInMHPCOsFavour(
188	    basePremium +
189	      itemSurchargesOf(items) +
190	      policyAdjustmentOf(basePremium, context) +
191	      PROCESSING_FEE,
192	  );
193	};
194	
195	const insuranceSumOf = (items: Item[]): number =>
196	  items.reduce(
197	    (total, item) => total + INSURANCE_VALUE_BY_ITEM_TYPE[item.type],
198	    0,
199	  );
200	
201	// A deductible applies per damage event, i.e. once per damaged item.
202	const payoutForDamage = (damage: Damage): number =>
203	  damage.amount - DEDUCTIBLE_PER_DAMAGE;
204	
205	// A policy is created by a quote step; claims draw down its remaining cap.
206	type Policy = { remainingCap: number };
207	
208	export const runScenario = (scenario: unknown): ScenarioOutcome => {
209	  const { customer, steps } = scenario as Scenario;
210	
211	  const policiesByStep = new Map<number, Policy>();
212	  const results: ScenarioResult[] = [];
213	  let precedingQuotes = 0;
214	
215	  steps.forEach((step, stepIndex) => {
216	    if (step.op === "quote") {
217	      results.push({
218	        premium: quotePremium(step.items, { customer, precedingQuotes }),
219	      });
220	      policiesByStep.set(stepIndex, {
221	        remainingCap:
222	          insuranceSumOf(step.items) * CAP_MULTIPLE_OF_INSURANCE_SUM,
223	      });
224	      precedingQuotes += 1;
225	      return;
226	    }
227	
228	    const policy = policiesByStep.get(step.policy) as Policy;
229	    const payout = step.incident.damages.reduce(
230	      (total, damage) => total + payoutForDamage(damage),
231	      0,
232	    );
233	
234	    policy.remainingCap -= payout;
235	    results.push({ payout, remainingCap: policy.remainingCap });
236	  });
237	
238	  return { results };
239	};
