// A policy is created by a quote step; claims draw down its remaining cap.
type Policy = { remainingCap: number };

export const runScenario = (scenario: unknown): ScenarioOutcome => {
  const { customer, steps } = scenario as Scenario;

  const policiesByStep = new Map<number, Policy>();
  const results: ScenarioResult[] = [];
  let precedingQuotes = 0;

  steps.forEach((step, stepIndex) => {
    if (step.op === "quote") {
      results.push({
        premium: quotePremium(step.items, { customer, precedingQuotes }),
      });
      policiesByStep.set(stepIndex, {
        remainingCap:
          insuranceSumOf(step.items) * CAP_MULTIPLE_OF_INSURANCE_SUM,
      });
      precedingQuotes += 1;
      return;
    }

    const policy = policiesByStep.get(step.policy) as Policy;
